import requests
import attr
import time
from functools import wraps
from taf.sw.neat.httpclient.ApiClientLocal import ApiClientLocal
from taf.sw.neat.httpclient.neat_uri import AuthURI


class AuthorizationFailed(Exception):
    pass


@attr.s(eq=True, frozen=True)
class TokenDetails(object):
    access_token = attr.ib(type=str)
    access_token_expires_in = attr.ib(type=int)
    refresh_token = attr.ib(type=str)
    refresh_token_expires_in = attr.ib(type=int)

    def __attrs_post_init__(self):
        object.__setattr__(self, "token_creation_time", time.time())


class Authorization(object):
    @staticmethod
    def get_access_token_details(host, username, password, refresh_token=None, timeout=60):
        token_url = 'https://{}/auth/realms/NADCM/protocol/openid-connect/token'.format(host)
        try:

            token_response = Authorization._get_token_response(token_url, username, password, refresh_token, timeout=timeout)
            return TokenDetails(
                access_token=token_response['access_token'],
                access_token_expires_in=token_response['expires_in'],
                refresh_token=token_response['refresh_token'],
                refresh_token_expires_in=int(token_response['refresh_expires_in'])
            )
        except Exception as e:
            raise AuthorizationFailed from e

    @staticmethod

    def _get_token_response(url, username, password, refresh_token=None, timeout=60):
        if refresh_token:
            request_data = {
                "grant_type": 'refresh_token',
                "client_id": 'curl',
                "refresh_token": refresh_token
            }
        else:
            request_data = {
                "grant_type": 'password',
                "client_id": 'curl',
                "username": username,
                "password": password
            }
        response = requests.post(
            url, data=request_data, verify=False, timeout=int(timeout)
        )

        response.raise_for_status()

        return response.json()

    @staticmethod
    def close_session(conn_details, token_details, timeout=30):
        url = f"https://{conn_details.host}:{conn_details.port}/auth/realms/nadcm/protocol/openid-connect/logout"
        data = {
                "client_id": "curl",
                "refresh_token": token_details.refresh_token
            }
        response = requests.post(url, data=data, verify=False, timeout=int(timeout))
        response.raise_for_status()

        return response.status_code

class TokenProvider(object):

    @staticmethod
    def _refresh_token_if_needed(service_instance):
        token_details = service_instance.token_details
        conn_details = service_instance.conn_details
        now = time.time()
        access_token_expiry = token_details.access_token_expires_in + token_details.token_creation_time
        refresh_token_expiry = token_details.refresh_token_expires_in + token_details.token_creation_time

        if access_token_expiry < now + 30:
            refresh_token = token_details.refresh_token if refresh_token_expiry > now else None
            token_details = Authorization.get_access_token_details(
                conn_details.host,
                conn_details.username,
                conn_details.password,
                refresh_token,
                conn_details.timeout
            )
            service_instance.token_details = token_details
            service_instance.access_token = token_details.access_token
            TokenProvider._update_access_token_for_clients(service_instance, token_details)

    @staticmethod
    def _update_access_token_for_clients(service_instance, token_details):
        for attribute in service_instance.__dict__:
            attr_value = getattr(service_instance, attribute)
            if hasattr(attr_value, 'api_client'):
                attr_value.api_client.token = token_details.access_token
            if hasattr(attr_value, 'http_api_client'):
                attr_value.http_api_client.token = token_details.access_token
            if hasattr(attr_value, 'configuration'):
                attr_value.configuration.access_token = token_details.access_token

    @staticmethod
    def provide_access_token(func):
        @wraps(func)
        def wrapper(service_instance, *args, **kwargs):
            TokenProvider._refresh_token_if_needed(service_instance)
            return func(service_instance, *args, **kwargs)
        return wrapper

class TokenRevoke(object):
    def __init__(self, configuration, token):
        self.api_client = ApiClientLocal(configuration, token)

    def revoke_token(self, token_details, timeout=60):
        if token_details.access_token_expires_in + token_details.token_creation_time <= time.time():
            return
        revoke_data = {
            "client_id": "curl",
            "token_type_hint": "access_token",
            "token": self.api_client.token
        }
        return self.api_client.send_post_request(uri=AuthURI().revoke_token_uri, data=revoke_data, timeout=timeout)
